package app.litetube.player

import org.schabi.newpipe.extractor.MediaFormat
import org.schabi.newpipe.extractor.stream.StreamInfo
import org.schabi.newpipe.extractor.stream.SubtitlesStream
import java.util.Locale

/** One entry in the captions menu. */
data class CaptionOption(val language: String, val label: String, val stream: SubtitlesStream)

object Captions {

    /** Languages available for a video: one entry each, preferring human-made over auto-generated. */
    fun options(info: StreamInfo): List<CaptionOption> {
        val usable = info.subtitles.filter { it.isUrl && it.format == MediaFormat.VTT }
        return usable.groupBy { baseLanguage(it.languageTag) }
            .mapNotNull { (language, streams) ->
                val best = streams.firstOrNull { !it.isAutoGenerated } ?: streams.first()
                CaptionOption(language, label(best), best)
            }
            .sortedBy { it.label.lowercase() }
    }

    /** The track for a remembered language choice, or null if this video doesn't have it. */
    fun find(info: StreamInfo, language: String?): CaptionTrack? {
        if (language.isNullOrEmpty()) return null
        val option = options(info).firstOrNull { it.language == language } ?: return null
        return CaptionTrack(option.stream.content, "text/vtt", language)
    }

    /** "sr-Latn" -> "sr", "en-GB" -> "en": remember the language, not the regional variant. */
    fun baseLanguage(tag: String?): String =
        tag.orEmpty().substringBefore('-').substringBefore('_').lowercase(Locale.ROOT)

    private fun label(s: SubtitlesStream): String {
        val name = s.displayLanguageName?.takeIf { it.isNotBlank() }
            ?: Locale.forLanguageTag(baseLanguage(s.languageTag)).displayLanguage
        return name.replaceFirstChar { it.titlecase(Locale.getDefault()) }
    }
}
